/**
 * DEAL RISK ENGINE - the single source of truth for every derived value.
 * Mode: Run Once for All Items.
 *
 * Inputs (three, joined here so nothing downstream re-derives anything):
 *   $input.all()                             -> deal_alert_state rows
 *   $('HubSpot - Read Open Deals').all()     -> open deals
 *   $('Data Table - Get Deal Tracking').all()-> last-seen close dates per deal
 *
 * Owns: score, level, trend, fingerprint, push count, previous-state attachment,
 * display fields. Route Decision does routing only; it derives nothing.
 */

// ============================ TUNABLE BUSINESS RULES =========================
const THRESHOLDS          = { CRITICAL: 60, HIGH: 40, MODERATE: 20 };
const STALL_DAYS          = { LOSING: 14, STALLED: 30, SEVERE: 60 };
const HIGH_VALUE_MIN      = 100000;   // compared in HubSpot home currency
const DQ_WEIGHT           = 0.5;      // how much CRM hygiene contributes to the score
const NEW_DEAL_GRACE_DAYS = 7;        // a new deal is not "risky" for being incomplete
const TREND_DELTA         = 3;        // score move before trend stops reading STABLE
const HUBSPOT_PORTAL_ID   = 'YOUR_HUBSPOT_PORTAL_ID';
// =============================================================================

const MS_PER_DAY = 86400000;
const now = Date.now();
const assessedAt = new Date(now).toISOString();
const severityRank = { NONE: 0, LOW: 1, MEDIUM: 2, HIGH: 3, CRITICAL: 4 };

// Accepts ISO-8601 AND epoch-millisecond values. Returns null only when the value is
// genuinely unusable - never merely because HubSpot changed how it serialises dates.
const parseHsDate = (raw) => {
  if (raw === null || raw === undefined || raw === '') return null;
  if (raw instanceof Date) return Number.isNaN(raw.getTime()) ? null : raw;
  if (typeof raw === 'number') {
    const d = new Date(raw);
    return Number.isNaN(d.getTime()) ? null : d;
  }
  const s = String(raw).trim();
  if (s === '') return null;
  if (/^\d{10,}$/.test(s)) {
    const d = new Date(Number(s));
    return Number.isNaN(d.getTime()) ? null : d;
  }
  const d = new Date(s);
  return Number.isNaN(d.getTime()) ? null : d;
};

const toNumber = (raw) => {
  if (raw === null || raw === undefined || raw === '') return null;
  const n = Number(raw);
  return Number.isFinite(n) ? n : null;
};

const str = (v) => (v === null || v === undefined) ? '' : String(v);

// ---- Index the two state tables --------------------------------------------
const alertStateByDealId = new Map();
for (const item of $input.all()) {
  const row = item && item.json;
  if (!row || row.deal_id === null || row.deal_id === undefined || row.deal_id === '') continue;
  alertStateByDealId.set(String(row.deal_id), row);
}

const trackingByDealId = new Map();
for (const item of $('Data Table - Get Deal Tracking').all()) {
  const row = item && item.json;
  if (!row || row.deal_id === null || row.deal_id === undefined || row.deal_id === '') continue;
  trackingByDealId.set(String(row.deal_id), row);
}

const out = [];

for (const item of $('HubSpot - Read Open Deals').all()) {
  const json = (item && item.json) || {};
  const p = json.properties || {};
  const dealId = String(json.id === null || json.id === undefined ? '' : json.id).trim();

  // GUARD: never fabricate a deal from an empty or malformed row.
  if (!dealId) continue;

  const dealName   = str(p.dealname).trim();
  const amount     = toNumber(p.amount);
  const homeAmount = toNumber(p.amount_in_home_currency);
  const amountHome = homeAmount === null ? amount : homeAmount;
  const currency   = str(p.deal_currency_code).trim();

  // null (not 0) when the property is absent, so a missing property never scores.
  const contactCount = toNumber(p.num_associated_contacts);

  const closeDate     = parseHsDate(p.closedate);
  const salesActivity = parseHsDate(p.hs_last_sales_activity_timestamp);
  const lastContacted = parseHsDate(p.notes_last_contacted);
  const crmModified   = parseHsDate(p.hs_lastmodifieddate);

  // Prefer genuine sales activity. hs_lastmodifieddate is a CRM-write proxy that any
  // automation resets, which silently disables stall detection.
  const activityDate   = salesActivity || lastContacted || crmModified;
  const activitySource = salesActivity ? 'SALES_ACTIVITY'
                       : lastContacted ? 'LAST_CONTACTED'
                       : crmModified   ? 'CRM_LAST_MODIFIED'
                       : 'NONE';

  const createDate = parseHsDate(p.createdate);
  const ageDays = createDate ? Math.floor((now - createDate.getTime()) / MS_PER_DAY) : null;

  const stage    = str(p.dealstage);
  const pipeline = str(p.pipeline);
  const ownerId  = str(p.hubspot_owner_id);
  const nextStep = str(p.hs_next_step).trim();

  // ---- Close-date push detection ------------------------------------------
  // Watches EVERY open deal, not just alerted ones: a push is what causes risk,
  // so detecting it only on already-flagged deals would always be too late.
  const tracking = trackingByDealId.get(dealId);
  const closeDateIso = closeDate ? closeDate.toISOString() : '';
  let closeDatePushCount = tracking ? (toNumber(tracking.close_date_push_count) || 0) : 0;
  let trackingChanged = !tracking;

  if (tracking) {
    const prevMs = Date.parse(str(tracking.close_date));
    const curMs  = closeDate ? closeDate.getTime() : NaN;
    if (Number.isFinite(prevMs) && Number.isFinite(curMs)) {
      const movedDays = Math.floor((curMs - prevMs) / MS_PER_DAY);
      if (movedDays >= 1) {          // pushed out
        closeDatePushCount += 1;
        trackingChanged = true;
      } else if (movedDays <= -1) {  // pulled in - record, but never count as a push
        trackingChanged = true;
      }
    } else if (str(tracking.close_date) !== closeDateIso) {
      trackingChanged = true;
    }
  }

  const issues = [];
  const riskDrivers = [];
  const scoreBreakdown = {};
  let dealRiskScore = 0;      // genuine execution / forecast risk
  let dataQualityScore = 0;   // CRM hygiene, tracked separately
  let highestIssueSeverity = 'NONE';

  const add = (code, severity, points, driver, key, kind, detail) => {
    const issue = { code, severity, points, kind };
    if (detail) issue.detail = detail;
    issues.push(issue);
    if (kind === 'DQ') dataQualityScore += points;
    else dealRiskScore += points;
    scoreBreakdown[key] = points;
    riskDrivers.push(driver);
    if (severityRank[severity] > severityRank[highestIssueSeverity]) highestIssueSeverity = severity;
  };

  // ---- CRM data quality (contributes at DQ_WEIGHT, never alone drives HIGH) --
  if (amount === null || amount <= 0) {
    add('MISSING_OR_INVALID_AMOUNT', 'MEDIUM', 15,
      'Deal value missing or invalid, reducing forecast reliability.', 'missingAmount', 'DQ');
  }
  if (!ownerId) {
    add('UNASSIGNED_DEAL', 'HIGH', 10,
      'No deal owner assigned, creating execution risk.', 'missingOwner', 'DQ');
  }
  if (!nextStep) {
    add('MISSING_NEXT_STEP', 'MEDIUM', 10,
      'No documented next step, increasing execution risk.', 'missingNextStep', 'DQ');
  }
  if (!closeDate) {
    add('MISSING_CLOSE_DATE', 'HIGH', 15,
      'No reliable close date available for forecasting.', 'missingCloseDate', 'DQ');
  }
  if (!activityDate) {
    add('MISSING_ACTIVITY_DATA', 'MEDIUM', 5,
      'Activity timestamp missing, limiting momentum assessment.', 'missingActivity', 'DQ');
  }
  if (contactCount === 0) {
    add('NO_BUYER_CONTACT', 'MEDIUM', 15,
      'No contacts associated with this deal, so buyer coverage cannot be assessed.',
      'noBuyerContact', 'DQ');
  }

  // ---- Buyer coverage: single-threading ------------------------------------
  if (contactCount === 1) {
    add('SINGLE_THREADED', 'HIGH', 25,
      'Only one contact associated, so the deal depends on a single relationship.',
      'singleThreaded', 'RISK');
  }

  // ---- Forecast slippage: date already in the past --------------------------
  let daysToClose = null;
  if (closeDate) {
    daysToClose = Math.ceil((closeDate.getTime() - now) / MS_PER_DAY);
    if (daysToClose < 0) {
      const overdue = Math.abs(daysToClose);
      const points = overdue >= 91 ? 55
                   : overdue >= 61 ? 48
                   : overdue >= 31 ? 42
                   : overdue >= 15 ? 30
                   : overdue >= 8  ? 20
                   : 12;
      const severity = overdue >= 31 ? 'CRITICAL' : overdue >= 15 ? 'HIGH' : 'MEDIUM';
      add('EXPIRED_CLOSE_DATE', severity, points,
        'Close date ' + overdue + ' days overdue, indicating forecast slippage.',
        'expiredCloseDate', 'RISK', 'Expired ' + overdue + ' days ago');
    }
  }

  // ---- Forecast slippage: date that keeps moving ---------------------------
  // Distinct from the above: a deal pushed across three quarters is never overdue
  // on any single day, yet is one of the most reliable slip signals there is.
  if (closeDatePushCount >= 3) {
    add('CLOSE_DATE_REPEATEDLY_PUSHED', 'HIGH', 35,
      'Close date pushed ' + closeDatePushCount + ' times, timeline is not holding.',
      'closeDatePushed', 'RISK', closeDatePushCount + ' pushes');
  } else if (closeDatePushCount === 2) {
    add('CLOSE_DATE_PUSHED_TWICE', 'MEDIUM', 25,
      'Close date pushed twice, timeline confidence is weakening.', 'closeDatePushed', 'RISK');
  } else if (closeDatePushCount === 1) {
    add('CLOSE_DATE_PUSHED', 'LOW', 10,
      'Close date pushed once since first observed.', 'closeDatePushed', 'RISK');
  }

  // ---- Momentum -------------------------------------------------------------
  let inactiveDays = null;
  if (activityDate) {
    inactiveDays = Math.max(0, Math.floor((now - activityDate.getTime()) / MS_PER_DAY));
    if (inactiveDays >= STALL_DAYS.SEVERE) {
      add('SEVERELY_STALLED_DEAL', 'CRITICAL', 45,
        'No sales activity for ' + inactiveDays + ' days, deal momentum is dead.', 'severelyStalled', 'RISK');
    } else if (inactiveDays >= STALL_DAYS.STALLED) {
      add('STALLED_DEAL', 'HIGH', 35,
        'No sales activity for ' + inactiveDays + ' days, deal is stalling.', 'stalled', 'RISK');
    } else if (inactiveDays >= STALL_DAYS.LOSING) {
      add('LOSING_MOMENTUM', 'MEDIUM', 18,
        'Activity aging at ' + inactiveDays + ' days, momentum slowing.', 'agingActivity', 'RISK');
    }
  }

  // ---- Near-close execution gap ---------------------------------------------
  if (daysToClose !== null && daysToClose >= 0 && daysToClose <= 7 &&
      inactiveDays !== null && inactiveDays >= 7) {
    add('NEAR_CLOSE_EXECUTION_GAP', 'HIGH', 20,
      'Close date is ' + daysToClose + ' days away with no recent activity.', 'nearCloseGap', 'RISK');
  }

  // ---- High value escalates, rather than being decorative -------------------
  const highValue = amountHome !== null && amountHome >= HIGH_VALUE_MIN;
  if (highValue && dealRiskScore > 0) {
    const bump = Math.min(15, Math.round(dealRiskScore * 0.25));
    dealRiskScore += bump;
    scoreBreakdown.highValueEscalation = bump;
    riskDrivers.push('High-value opportunity: prioritize risk review.');
  }

  // ---- Final score ----------------------------------------------------------
  const hygieneOnly = dealRiskScore === 0 && dataQualityScore > 0;
  const inGrace = ageDays !== null && ageDays <= NEW_DEAL_GRACE_DAYS;
  const dqApplied = (hygieneOnly && inGrace) ? 0 : Math.round(dataQualityScore * DQ_WEIGHT);
  const riskScore = Math.max(0, Math.min(100, dealRiskScore + dqApplied));

  const riskLevel = riskScore >= THRESHOLDS.CRITICAL ? 'CRITICAL'
                  : riskScore >= THRESHOLDS.HIGH     ? 'HIGH'
                  : riskScore >= THRESHOLDS.MODERATE ? 'MODERATE'
                  : 'LOW';

  // ---- Attach previous alert state + trend ---------------------------------
  const previous = alertStateByDealId.get(dealId);
  const previousRiskScore = previous ? toNumber(previous.risk_score) : null;
  let riskTrend = 'NEW';
  if (previous && previousRiskScore !== null) {
    const delta = riskScore - previousRiskScore;
    riskTrend = delta >= TREND_DELTA ? 'RISING'
              : delta <= -TREND_DELTA ? 'FALLING'
              : 'STABLE';
  }

  const issueCodes = issues.map(i => i.code);
  const uniqueDrivers = [...new Set(riskDrivers)];

  out.push({
    json: {
      dealId,
      dealName,
      dealNameSafe: (dealName || 'Unnamed deal').replace(/[{}]/g, ' ').slice(0, 160),
      dealUrl: 'https://app.hubspot.com/contacts/' + HUBSPOT_PORTAL_ID + '/record/0-3/' + dealId,
      ownerId,
      amount,
      amountHome,
      currency,
      amountDisplay: amount === null ? 'NOT RECORDED' : amount.toLocaleString('en-US', { maximumFractionDigits: 0 }),
      stage,
      pipeline,
      nextStep,
      contactCount,
      closeDate: closeDateIso || null,
      closeDatePushCount,
      trackingChanged,
      lastActivityAt: activityDate ? activityDate.toISOString() : null,
      activitySource,
      ageDays,
      inactiveDays,
      daysToClose,
      highValue,
      riskScore,
      dealRiskScore,
      dataQualityScore,
      riskLevel,
      riskTrend,
      highestIssueSeverity,
      issueCodes,
      issueFingerprint: [...new Set(issueCodes)].sort().join(','),
      riskDrivers: uniqueDrivers,
      riskDriversText: uniqueDrivers.map(d => '    - ' + d).join('\n'),
      scoreBreakdown: Object.assign({}, scoreBreakdown, {
        dealRisk: dealRiskScore,
        dataQuality: dataQualityScore,
        dataQualityApplied: dqApplied,
        final: riskScore
      }),
      // Previous alert state, attached here so no downstream node reads the table.
      hasPreviousState: !!previous,
      previousRiskScore,
      previousRiskLevel: previous ? str(previous.risk_level) : '',
      previousIssueFingerprint: previous ? str(previous.issue_fingerprint) : '',
      firstAlertedAt: previous ? str(previous.first_alerted_at) : '',
      assessedAt
    }
  });
}

// May legitimately be empty (zero open deals). "Always Output Data" is enabled so the
// run-summary branch still executes and records dealsScanned = 0.
return out;

/**
 * RUN SUMMARY - exactly one rollup row per scheduled run, including zero-deal runs.
 * Mode: Run Once for All Items.
 */
const rows = $input.all().filter(i => i && i.json && i.json.dealId);
const runTimestamp = (rows.length && rows[0].json.assessedAt) || new Date().toISOString();

const counts = { LOW: 0, MODERATE: 0, HIGH: 0, CRITICAL: 0 };
let highValueRiskCount = 0;
let singleThreadedCount = 0;
let dataQualityOnlyCount = 0;    // HIGH/CRITICAL flagged purely on CRM hygiene
let missingCloseDateCount = 0;   // tripwire: a HubSpot date-format change spikes this
let totalExposureHighCritical = 0;

for (const { json: row } of rows) {
  if (row.riskLevel in counts) counts[row.riskLevel]++;

  const codes = Array.isArray(row.issueCodes) ? row.issueCodes : [];
  if (codes.indexOf('SINGLE_THREADED') !== -1) singleThreadedCount++;
  if (codes.indexOf('MISSING_CLOSE_DATE') !== -1) missingCloseDateCount++;

  const atRisk = row.riskLevel === 'HIGH' || row.riskLevel === 'CRITICAL';
  if (atRisk && row.highValue) highValueRiskCount++;
  if (atRisk && Number(row.dealRiskScore) === 0) dataQualityOnlyCount++;
  if (atRisk) {
    const raw = (row.amountHome === null || row.amountHome === undefined) ? row.amount : row.amountHome;
    const amt = Number(raw);
    if (Number.isFinite(amt)) totalExposureHighCritical += amt;
  }
}

return [{
  json: {
    runTimestamp,
    executionId: $execution.id,
    dealsScanned: rows.length,
    lowRiskCount: counts.LOW,
    moderateRiskCount: counts.MODERATE,
    highRiskCount: counts.HIGH,
    criticalRiskCount: counts.CRITICAL,
    highValueRiskCount,
    singleThreadedCount,
    dataQualityOnlyCount,
    missingCloseDateCount,
    totalExposureHighCritical: Math.round(totalExposureHighCritical * 100) / 100
  }
}];

/**
 * TRACKING UPSERTS - writes the deal_tracking row only for deals whose close date
 * actually moved (or that have never been seen before).
 * Mode: Run Once for All Items.
 *
 * Writing every deal every run would mean one DB write per open deal per day for no
 * benefit; in steady state only a small fraction of deals move their close date.
 *
 * Note: deal_tracking is deliberately NOT auto-reaped. A stale row for a closed deal
 * is inert - it is only ever read for deals present in the current scan - and if the
 * deal reopens its push history is correctly preserved.
 */
const seenAt = new Date().toISOString();

return $input.all()
  .filter(i => i && i.json && i.json.dealId && i.json.trackingChanged === true)
  .map(({ json: deal }) => ({
    json: {
      dealId: String(deal.dealId),
      closeDate: deal.closeDate === null || deal.closeDate === undefined ? '' : String(deal.closeDate),
      closeDatePushCount: Number(deal.closeDatePushCount) || 0,
      lastSeenAt: seenAt
    }
  }));

/**
 * STATE REAPER - removes deal_alert_state rows for deals that have left the pipeline
 * (closed won/lost, deleted, moved out of scope). Those deals never reappear in the
 * scan, so the resolution branch can never clear them.
 * Mode: Run Once for All Items.
 *
 * Output feeds BOTH the alert-state delete AND the Resolved Log, so a deal leaving the
 * pipeline is recorded rather than silently vanishing. Field names match the RESOLVED
 * branch of Code - Route Decision so one sheet node serves both producers.
 *
 * Two safety rules, both deliberate:
 *   1. Never reap on a run that scanned zero deals.
 *   2. Never reap a row younger than STALE_DAYS.
 * Without these, one transient HubSpot outage would wipe the state table and cause a
 * full re-alert storm the following morning.
 */
const STALE_DAYS = 30;
const MS_PER_DAY = 86400000;
const cutoff = Date.now() - STALE_DAYS * MS_PER_DAY;

const scanned = $input.all().filter(i => i && i.json && i.json.dealId);
if (scanned.length === 0) return [];

const scannedIds = new Set(scanned.map(i => String(i.json.dealId)));
const reapedAt = new Date().toISOString();
const str = (v) => (v === null || v === undefined) ? '' : String(v);
const orphans = [];

for (const item of $('Data Table - Get Alert State').all()) {
  const row = item && item.json;
  if (!row || row.deal_id === null || row.deal_id === undefined || row.deal_id === '') continue;

  const id = String(row.deal_id);
  if (scannedIds.has(id)) continue;

  const lastAlertedMs = Date.parse(str(row.last_alerted_at));
  if (!Number.isFinite(lastAlertedMs) || lastAlertedMs >= cutoff) continue;

  // The deal became invisible somewhere between last_alerted_at and now, so measure
  // the at-risk window to the last confirmed alert rather than to detection time.
  const firstMs = Date.parse(str(row.first_alerted_at));
  const daysAtRisk = Number.isFinite(firstMs)
    ? Math.max(0, Math.floor((lastAlertedMs - firstMs) / MS_PER_DAY))
    : '';

  orphans.push({
    json: {
      dealId: id,
      dealName: str(row.deal_name),
      ownerId: '',
      resolutionReason: 'NOT_IN_PIPELINE',
      lastAlertedRiskLevel: str(row.risk_level),
      lastAlertedRiskScore: row.risk_score === null || row.risk_score === undefined ? '' : row.risk_score,
      lastAlertedIssueFingerprint: str(row.issue_fingerprint),
      newRiskLevel: '',
      newRiskScore: '',
      daysAtRisk,
      resolvedAt: reapedAt
    }
  });
}

return orphans;

/**
 * ROUTE DECISION - the single state machine for "what should happen to this deal".
 * Mode: Run Once for All Items.
 *
 * Pure routing. Every value it reads was computed by Code - Deal Risk Engine and
 * attached to the item, so nothing is derived twice.
 * Output: every scanned deal, tagged route = NEEDS_AI | REFRESH | RESOLVED | NOOP
 */
const ALERT_SCORE_CHANGE_THRESHOLD = 5;
const ALERTING_LEVELS = new Set(['HIGH', 'CRITICAL']);
const MS_PER_DAY = 86400000;

const decidedAt = new Date().toISOString();
const decidedMs = Date.parse(decidedAt);

const daysAtRiskFrom = (firstAlertedAt, endMs) => {
  const firstMs = Date.parse(String(firstAlertedAt || ''));
  return Number.isFinite(firstMs) ? Math.max(0, Math.floor((endMs - firstMs) / MS_PER_DAY)) : '';
};

return $input.all()
  .filter(i => i && i.json && i.json.dealId)
  .map(({ json: deal }) => {
    const atRisk = ALERTING_LEVELS.has(deal.riskLevel);

    // ---- Not at risk --------------------------------------------------------
    if (!atRisk) {
      if (!deal.hasPreviousState) {
        return { json: Object.assign({}, deal, { route: 'NOOP', alertReason: 'NOT_AT_RISK' }) };
      }
      // Previously alerted and has now dropped below the threshold -> resolution.
      return {
        json: Object.assign({}, deal, {
          route: 'RESOLVED',
          alertReason: 'RISK_RESOLVED',
          resolutionReason: 'RISK_IMPROVED',
          lastAlertedRiskLevel: deal.previousRiskLevel,
          lastAlertedRiskScore: deal.previousRiskScore === null ? '' : deal.previousRiskScore,
          lastAlertedIssueFingerprint: deal.previousIssueFingerprint,
          newRiskLevel: deal.riskLevel,
          newRiskScore: deal.riskScore,
          daysAtRisk: daysAtRiskFrom(deal.firstAlertedAt, decidedMs),
          resolvedAt: decidedAt,
          actionStatus: 'RESOLVED'
        })
      };
    }

    // ---- At risk: has anything MATERIAL changed since the last alert? -------
    let shouldAlert = false;
    let alertReason = 'DUPLICATE_RISK_STATE';

    if (!deal.hasPreviousState) {
      shouldAlert = true;
      alertReason = 'NEW_RISK_ALERT';
    } else if (String(deal.previousRiskLevel) !== String(deal.riskLevel)) {
      shouldAlert = true;
      alertReason = 'RISK_LEVEL_CHANGED';
    } else if (String(deal.previousIssueFingerprint) !== String(deal.issueFingerprint)) {
      shouldAlert = true;
      alertReason = 'RISK_ISSUES_CHANGED';
    } else if (deal.previousRiskScore === null) {
      // Fail open, but say so, instead of masquerading as a real score change.
      shouldAlert = true;
      alertReason = 'STATE_SCORE_UNREADABLE';
    } else if (Math.abs(Number(deal.previousRiskScore) - Number(deal.riskScore)) >= ALERT_SCORE_CHANGE_THRESHOLD) {
      shouldAlert = true;
      alertReason = 'RISK_SCORE_CHANGED';
    }

    // Stamped on the first alert, preserved forever after.
    const firstAlertedAt = deal.firstAlertedAt || decidedAt;

    return {
      json: Object.assign({}, deal, {
        route: shouldAlert ? 'NEEDS_AI' : 'REFRESH',
        shouldAlert,
        alertReason,
        firstAlertedAt,
        daysAtRisk: daysAtRiskFrom(firstAlertedAt, decidedMs),
        actionStatus: 'REVIEW_REQUIRED'
      })
    };
  });

/**
 * MERGE AI - left-joins the model's single output onto the authoritative list of deals
 * that were sent to it.
 * Mode: Run Once for All Items.
 *
 * The model now produces one field: next_best_action. Everything else in the alert is
 * deterministic, so a failed, weak or unmatched AI response degrades the WORDING of one
 * line and can never delete an alert.
 */
const MIN_WORDS = 8;

const gated = $('Code - Route Decision').all()
  .filter(i => i && i.json && i.json.route === 'NEEDS_AI');

const actionByDealId = new Map();
for (const item of $input.all()) {
  const ai = (item && item.json && item.json.output) || {};
  const id = String(ai.deal_id === null || ai.deal_id === undefined ? '' : ai.deal_id).trim();
  if (id && !actionByDealId.has(id)) actionByDealId.set(id, ai.next_best_action);
}

// The prompt asks for a minimum length; enforce it here too. The schema alone cannot
// stop a terse-but-valid answer such as "Follow up." reaching a Slack channel.
const usable = (v) => {
  if (typeof v !== 'string') return null;
  const t = v.trim();
  if (!t) return null;
  return t.split(/\s+/).filter(Boolean).length >= MIN_WORDS ? t : null;
};

// Deterministic fallback built from the top risk driver, so an LLM outage produces a
// specific instruction rather than boilerplate.
const fallbackAction = (d) => {
  const codes = Array.isArray(d.issueCodes) ? d.issueCodes : [];
  if (codes.indexOf('SINGLE_THREADED') !== -1)
    return 'Identify and engage a second stakeholder this week before advancing the deal.';
  if (codes.indexOf('SEVERELY_STALLED_DEAL') !== -1 || codes.indexOf('STALLED_DEAL') !== -1)
    return 'Contact the buyer this week to confirm whether the evaluation is still active.';
  if (codes.indexOf('EXPIRED_CLOSE_DATE') !== -1 || codes.indexOf('CLOSE_DATE_REPEATEDLY_PUSHED') !== -1)
    return 'Re-confirm the buyer timeline and set a close date the deal can actually hold.';
  if (codes.indexOf('MISSING_NEXT_STEP') !== -1)
    return 'Agree a dated next step with the buyer and record it on the deal this week.';
  return 'Review the highest-priority risk driver and update the deal record this week.';
};

return gated.map(({ json: deal }) => {
  const raw = actionByDealId.get(String(deal.dealId));
  const action = usable(raw);
  return {
    json: Object.assign({}, deal, {
      actionSource: action ? 'AI' : 'FALLBACK',
      recommendedAction: action || fallbackAction(deal)
    })
  };
});

