/**
 * CONFIRM DELIVERY - runs only on a Slack node's SUCCESS output.
 * Mode: Run Once for Each Item.
 *
 * Two jobs: emit the Alert Log row (proof the alert was delivered) and the payload for
 * the alert-state upsert. Both happen only after Slack confirms the send, so a failed
 * send neither records state nor fabricates a delivery record - the deal simply
 * re-alerts next run.
 *
 * The Slack node returns the Slack API response, not the deal, so the deal is resolved
 * through n8n item linking. If that link cannot be established we throw rather than
 * guess: not recording state is the safe direction.
 */
const CHANNEL_BY_NODE = {
  'Slack - Critical Risk Alert': '#revops-risk',
  'Slack - High Risk Alert': '#revops-risk',
  'Slack - Risk Routing Exception': '#workflow-error'
};

let deal;
try {
  deal = $('Code - Merge AI').item.json;
} catch (e) {
  throw new Error('Delivered Slack alert could not be traced back to its deal. Alert state was NOT recorded; this deal will re-alert on the next run.');
}

const dealId = String(deal && deal.dealId ? deal.dealId : '').trim();
if (!dealId) {
  throw new Error('Delivered Slack alert resolved to a record with no dealId. Alert state was NOT recorded.');
}

let sourceNode = '';
try {
  if (typeof $prevNode !== 'undefined' && $prevNode && $prevNode.name) sourceNode = $prevNode.name;
} catch (e) {
  // $prevNode unavailable here; fall through to the severity-based default.
}

const str = (v) => (v === null || v === undefined) ? '' : String(v);
const riskLevel = str(deal.riskLevel);
const slackChannel = CHANNEL_BY_NODE[sourceNode] ||
  ((riskLevel === 'CRITICAL' || riskLevel === 'HIGH') ? '#revops-risk' : '#workflow-error');

const score = Number(deal.riskScore);
const alertedAt = new Date().toISOString();

return {
  json: {
    dealId,
    dealName: str(deal.dealName),
    ownerId: str(deal.ownerId),
    riskLevel,
    riskScore: Number.isFinite(score) ? score : 0,
    issueFingerprint: str(deal.issueFingerprint),
    alertReason: str(deal.alertReason),
    actionSource: str(deal.actionSource),
    slackChannel,
    // Owned by Code - Route Decision; never re-derived here.
    firstAlertedAt: str(deal.firstAlertedAt) || alertedAt,
    alertedAt
  }
};

/**
 * AGGREGATE ERROR - the single error sink for the whole workflow.
 * Mode: Run Once for All Items.
 *
 * N failed items become ONE Slack message, and the message names the affected deals.
 * Per-item formatters turned an LLM or Sheets outage into a message storm that then
 * tripped Slack's own rate limit, and named the node but never the deals.
 */
const items = $input.all();

let source = 'Unknown node';
try {
  if (typeof $prevNode !== 'undefined' && $prevNode && $prevNode.name) source = $prevNode.name;
} catch (e) {
  // $prevNode not available in this context; fall through to the default.
}

const MAX_LINES = 20;
const lines = [];
const affected = [];

for (const item of items) {
  const json = (item && item.json) || {};
  const err = json.error || null;
  const rawId = json.dealId !== undefined && json.dealId !== null ? json.dealId : json.deal_id;
  const id = rawId === undefined || rawId === null || rawId === '' ? null : String(rawId);
  if (id) affected.push(id);

  let msg;
  if (err) {
    msg = String(err && err.message !== undefined && err.message !== null ? err.message : err);
  } else if (json.route) {
    msg = 'Item reached the error sink with an unexpected route "' + json.route + '"';
  } else {
    msg = 'Unknown error';
  }

  if (lines.length < MAX_LINES) lines.push(id ? '- ' + id + ': ' + msg : '- ' + msg);
}
if (items.length > MAX_LINES) lines.push('- ...and ' + (items.length - MAX_LINES) + ' more');

return [{
  json: {
    failedNode: source,
    failureCount: items.length,
    errorMessage: lines.length ? lines.join('\n') : 'No error detail available',
    affectedDealIds: affected,
    occurredAt: new Date().toISOString(),
    executionId: $execution.id
  }
}];
